import { createHash } from 'node:crypto'

// This catalog is generated by trusted controller code, never from a feature
// artifact. Its exact shape matches the reviewed Status endpoint contract.
export function fixtureCatalog(fixtureWorker, sha, casEnabled = false) {
  if (typeof fixtureWorker !== 'string' || !/^[a-z0-9-]+-fixture$/.test(fixtureWorker) || !/^[a-f0-9]{40}$/.test(sha) || typeof casEnabled !== 'boolean') throw new Error('Invalid fixture identity')
  const endpoint = (id, name, pathname) => ({ id, name, url: `https://preview-fixture.invalid${pathname}`, binding: 'PREVIEW_FIXTURE', serviceId: fixtureWorker, revision: sha })
  const monitor = endpoint('preview-monitor', 'Preview monitor', '/monitor')
  const action = endpoint('preview-action', 'Preview action', '/actions/success')
  const cas = casEnabled ? { ...endpoint('preview-cas', 'Preview CAS', '/cas-health'), authProviders: { cas: endpoint('preview-cas-provider', 'Preview CAS provider', '/cas/v1/tickets') } } : null
  return { endpoints: [monitor, ...(cas ? [cas] : [])], actions: [action] }
}

// Reviewed #90 algorithm: no requestPolicy is generated by fixtureCatalog;
// CAS identity includes both ordered provider slots, even if OAuth is absent.
export function fixtureRegistryStatements(fixtureWorker, sha, casEnabled = false) {
  const { endpoints } = fixtureCatalog(fixtureWorker, sha, casEnabled)
  return endpoints.map(endpoint => {
    const identity = [endpoint.url, endpoint.binding, endpoint.serviceId, endpoint.revision]
    if (endpoint.authProviders) {
      const cas = endpoint.authProviders.cas
      identity.push(['authProviders', null, [cas.id, cas.url, cas.binding, cas.serviceId, cas.revision]])
    }
    return {
      sql: 'INSERT INTO endpoint_registry (endpoint_id, fingerprint) VALUES (?, ?) ON CONFLICT(endpoint_id) DO UPDATE SET fingerprint=excluded.fingerprint',
      params: [endpoint.id, createHash('sha256').update(JSON.stringify(identity)).digest('hex')],
    }
  })
}
